-- mod-companion-auras uninstall: generated by tools/generate.py. Run by hand only when removing the module.

-- World database. Run this first: it needs the module's table to find the companion items.
UPDATE `item_template` SET `description` = TRIM(SUBSTRING_INDEX(`description`, 'Companion:', 1))
    WHERE `entry` IN (SELECT `item_entry` FROM `mod_companion_auras`);
DELETE FROM `spell_dbc` WHERE `ID` IN (951000, 951100, 951001, 951101, 951002, 951003, 951004, 951005, 951006, 951007, 951008, 951009, 951010, 951011, 951012, 951013, 951014, 951015, 951016, 951017, 951018, 951019, 951020, 951021, 951022, 951023, 951024, 951025, 951026, 951027, 951028, 951029, 951030, 951031, 951032, 951033, 951034, 951035);
DROP TABLE IF EXISTS `mod_companion_auras`;
